  "jungle.howTo.1": "Je zit vast in de jungle — maak overlevingskeuzes",
  "jungle.howTo.2": "Elke keuze beïnvloedt je HP en score anders",
  "jungle.howTo.3": "Als je HP 0 bereikt, is het spel afgelopen",
  "jungle.howTo.4": "Overleef alle 8 scenario’s om te winnen!",
  "jungle.scene6": "Je vindt een gewonde vogel. Wat doe je?",
  "jungle.s6c1": "Draag hem voorzichtig — misschien leidt dit je naar een pad (+5 HP, +25 pts)",
  "jungle.s6c2": "Laat hem liggen — zorgen kost energie (0 HP, +10 pts)",
  "jungle.scene7": "Een rivier verspert je pad. Het water lijkt snel.",
  "jungle.s7c1": "Bouw een vlot van omgevallen boomstammen (−5 HP, +40 pts)",
  "jungle.s7c2": "Loop stroomopwaarts om een ondiepe oversteek te vinden (+10 HP, +20 pts)",
  "jungle.scene8": "Je ziet rook in de verte.",
  "jungle.s8c1": "Ga op de rook af — misschien is het een reddingsactie! (+15 HP, +45 pts)",
  "jungle.s8c2": "Vermijd het — het kan een bosbrand zijn (−5 HP, +15 pts)",
  "jungle.scene9": "De nacht valt. Je hebt onderdak nodig.",
  "jungle.s9c1": "Klim in een hoge boom om veilig te zijn voor roofdieren (+10 HP, +30 pts)",
  "jungle.s9c2": "Bouw een schuilplaats op de grond met takken (−5 HP, +35 pts)",
  "jungle.scene10": "Je vindt een vrucht die je niet herkent. Je hebt heel veel honger.",
  "jungle.s10c1": "Eet hem — je verhongert! (−20 HP, +30 pts)",
  "jungle.s10c2": "Test eerst een klein stukje op je huid (0 HP, +20 pts)",
  "jungle.scene11": "Een grote slang rolt over het pad.",
  "jungle.s11c1": "Ga langzaam achteruit en zoek een omweg (+5 HP, +30 pts)",
  "jungle.s11c2": "Probeer hem weg te jagen (−25 HP, +40 pts)",
  "jungle.scene12": "Je hoort een waterval — je watervoorraad is kritiek laag.",
  "jungle.s12c1": "Volg het geluid voor vers water (+20 HP, +35 pts)",
  "jungle.s12c2": "Negeer het en ga verder (−15 HP, +20 pts)",
  "jungle.scene13": "Er komt snel een storm op.",
  "jungle.s13c1": "Zoek hoger gelegen grond en dekking (+10 HP, +25 pts)",
  "jungle.s13c2": "Blijf bewegen om eraan te ontsnappen (−10 HP, +30 pts)",
  "jungle.scene14": "Je vindt een grot. Het wordt donker.",
  "jungle.s14c1": "Ga de grot in voor onderdak (+15 HP, +30 pts)",
  "jungle.s14c2": "Slaap onder een boom — de grot kan bezet zijn (+5 HP, +20 pts)",
  "jungle.scene15": "Je bent uitgeput. Voor je lijkt een open plek veilig.",
  "jungle.s15c1": "Rust uit en herstel (+20 HP, +20 pts)",
  "jungle.s15c2": "Ga door — rust is hier gevaarlijk (−5 HP, +30 pts)",
  "jungle.scene16": "Je vindt een oude kaart die in een boom is gekerfd.",
  "jungle.s16c1": "Volg de richting van de kaart (+5 HP, +40 pts)",
  "jungle.s16c2": "Negeer het — het kan verouderd zijn (0 HP, +10 pts)",
  "jungle.scene17": "Wilde zwijnen steken agressief je pad over.",
  "jungle.s17c1": "Klim meteen in de dichtstbijzijnde boom (+5 HP, +30 pts)",
  "jungle.s17c2": "Blijf staan en schreeuw (−20 HP, +35 pts)",
  "jungle.scene18": "Je vindt een verlaten kamp met voorraden.",
  "jungle.s18c1": "Neem alles wat nuttig is (+20 HP, +50 pts)",
  "jungle.s18c2": "Laat het liggen — iemand heeft het later misschien nodig (0 HP, +10 pts)",
  "jungle.scene19": "Een aap steelt je voedselzak!",
  "jungle.s19c1": "Jaag de aap na (−10 HP, +40 pts)",
  "jungle.s19c2": "Laat hem gaan — het kost te veel energie (+0 HP, +15 pts)",
  "jungle.scene20": "Je hoort een helikopter boven je.",
  "jungle.s20c1": "Steek meteen een signaalvuur aan! (+30 HP, +60 pts)",
  "jungle.s20c2": "Waaier met je armen — misschien ziet hij je (+5 HP, +40 pts)",
